// Your saved shapes stay put when this script runs.
// This ball belongs to the script. Try changing its color.
const ball = new Ellipse({
  name: 'bouncing-ball',
  position: pt(420, 380),
  extent: pt(36, 36),
  fill: '#729b78'
});
world.addMorph(ball);
ball.addScript(function step() {
  this.position = pt(this.position.x,
    370 + Math.abs(Math.sin(performance.now() / 500)) * 65);
});
ball.startStepping(16);
console.log('Welcome to Livelier. Make something yours.');

